const finance = window.financeDemo;
const loanId = new URLSearchParams(location.search).get('id');
const loan = finance.getLoan(loanId);
const root = document.documentElement;
const content = document.querySelector('#loanContent');
const dialog = document.querySelector('#loanDialog');
let toastTimer;
function setTheme(theme) { root.dataset.theme = theme; const button = document.querySelector('.theme-button'); const dark = theme === 'dark'; button.setAttribute('aria-pressed', String(dark)); button.querySelector('.theme-label').textContent = dark ? 'Modo claro' : 'Modo oscuro'; localStorage.setItem('pw-theme', theme); }
function statusLabel(status) { return ({ overdue: 'Vencido', 'due-soon': 'Próximo a vencer', active: 'Activo', paid: 'Pagado' })[status] || 'Activo'; }
function eventLabel(type) { return type === 'disbursement' ? 'Desembolso registrado' : 'Pago registrado'; }
function showToast(message) { const toast = document.querySelector('#financeToast'); clearTimeout(toastTimer); toast.textContent = message; toast.hidden = false; toastTimer = setTimeout(() => { toast.hidden = true; }, 3200); }
function render() { if (!loan) { content.innerHTML = '<div class="finance-empty"><strong>No encontramos este préstamo.</strong><p>Regresa al listado para elegir un registro disponible.</p><a class="primary-action" href="loans.html">Ver préstamos</a></div>'; return; } const canPay = loan.balance > 0; content.innerHTML = `<div class="page-intro"><div><a class="finance-link" href="loans.html">← Volver a préstamos</a><h2>${loan.label}</h2><p>${loan.counterparty} · ${loan.direction === 'received' ? 'Préstamo recibido' : 'Préstamo otorgado'} · ${loan.frequency}</p></div>${canPay ? `<button class="primary-action" type="button" id="openLoanDialog">Registrar pago</button>` : ''}</div><section class="loan-summary"><div><span class="status-badge is-${loan.status}">${statusLabel(loan.status)}</span><h2>${finance.formatMoney(loan.balance)}</h2><p>Saldo pendiente de ${finance.formatMoney(loan.originalAmount)} original.</p></div><div><small>Próxima cuota</small><strong>${finance.formatMoney(loan.nextInstallment)}</strong></div><div><small>Vencimiento</small><strong>${loan.dueDate}</strong></div><div><small>Impacto</small><strong>Saldo general</strong></div></section><section class="loan-detail-grid"><div class="finance-panel"><div class="finance-panel-heading"><div><h3>Calendario de cuotas</h3><p>Estado de los compromisos acordados.</p></div></div><div class="table-region"><table><thead><tr><th>Cuota</th><th>Vencimiento</th><th>Monto</th><th>Estado</th></tr></thead><tbody>${loan.schedule.map((item) => `<tr><td>${item.number}</td><td>${item.dueDate}</td><td>${finance.formatMoney(item.amount)}</td><td><span class="status-badge is-${item.status}">${statusLabel(item.status)}</span></td></tr>`).join('')}</tbody></table></div></div><aside class="finance-panel"><div class="finance-panel-heading"><div><h3>Historial</h3><p>Eventos que ya impactaron el saldo general.</p></div></div><ul class="timeline">${loan.events.map((event) => `<li><strong>${eventLabel(event.type)} · ${finance.formatMoney(event.amount)}</strong><small>${event.date} · Saldo general</small></li>`).join('')}</ul><a class="secondary-action" href="financial-movements.html?origin=loan">Ver movimientos de préstamo</a></aside></section>`; document.querySelector('#openLoanDialog')?.addEventListener('click', openDialog); }
function openDialog() { document.querySelector('#loanForm').reset(); document.querySelector('#loanError').hidden = true; document.querySelector('#loanDialogTitle').textContent = 'Registrar pago'; document.querySelector('#loanSubmit').textContent = 'Registrar pago'; dialog.showModal(); document.querySelector('[name="amount"]').focus(); }
setTheme(localStorage.getItem('pw-theme') || 'light'); document.querySelector('.theme-button').addEventListener('click', () => setTheme(root.dataset.theme === 'dark' ? 'light' : 'dark')); document.querySelector('.dialog-close').addEventListener('click', () => dialog.close()); document.querySelector('[data-close-dialog]').addEventListener('click', () => dialog.close()); document.querySelector('#loanForm').addEventListener('submit', (event) => { event.preventDefault(); if (!loan) return; const data = Object.fromEntries(new FormData(event.currentTarget)); const result = finance.addLoanEvent(loan.id, { ...data, type: 'payment' }); const error = document.querySelector('#loanError'); if (!result.ok) { error.textContent = result.error; error.hidden = false; return; } dialog.close(); render(); showToast('Pago registrado y movimiento financiero creado.'); }); render();
